def family_instances(tuples):
    """Flatten a family into instrument records (r_vector, t)."""
    out = []
    for tp in tuples:
        for key in ('root_low', 'root_high', 'root'):
            if key in tp:
                rec = tp[key]
                out.append(([Fr(x) for x in rec['r']], Fr(rec['t'])))
    return out

